329	   * Ответ раунда. Если `publicView` игры падает, а раунд уже закрыт или ответ нужен для `open`,
330	   * отдаётся `view: null`, чтобы сломанное отображение не блокировало игру и не прятало итог раунда.
331	   */
332	  #view(round: RoundRecord, balance: number, safe: boolean): RoundView {
333	    let view: unknown = null;
334	    // Раунд, ждущий выплаты, игра уже завершила: ходов нет, показывать нечего до закрытия.
335	    if (!round.voided && round.pendingBet !== true && round.pendingPayout === null) {
336	      try {
337	        const game = this.games.get(round.gameId);
338	        if (!game) throw new Error(`Игра ${round.gameId} не подключена`);
339	        view = toJson(game.publicView(round.state, round.status === 'closed'));
340	      } catch (e) {
341	        const err = internal(`Игра ${round.gameId} не смогла показать раунд ${round.roundId}: ${detailOf(e)}`);
342	        if (!safe && round.status === 'open') throw err;
343	        console.error(`${err.code}: ${err.detail}`);
344	        view = null;
345	      }
346	    }
347	    return { roundId: round.roundId, gameId: round.gameId, bet: round.bet, status: round.status, view, payout: round.payout, balance };
348	  }
