357	/** Ставка: конечное число, округлённое до центов и попадающее в лимиты. Иначе `BET_OUT_OF_LIMITS`. */
358	function checkBet(bet: unknown): number {
359	  if (typeof bet !== 'number' || !Number.isFinite(bet)) throw new PlatformError('BET_OUT_OF_LIMITS');
360	  const amount = round2(bet);
361	  if (amount < LIMITS.min || amount > LIMITS.max) throw new PlatformError('BET_OUT_OF_LIMITS');
362	  return amount;
363	}
