397	function isValidStep(step: unknown): step is { status: 'continue'; state: unknown } | { status: 'finished'; state: unknown; payout: number } {
398	  if (!step || typeof step !== 'object') return false;
399	  const s = step as { status?: unknown; payout?: unknown };
400	  if (s.status === 'continue') return true;
401	  return s.status === 'finished' && typeof s.payout === 'number' && Number.isFinite(s.payout) && s.payout >= 0;
