406	  if (value === undefined) return value;
407	  try {
408	    return JSON.parse(JSON.stringify(value)) as T;
409	  } catch (e) {
410	    throw internal(`Состояние игры не сериализуется в JSON: ${messageOf(e)}`);
411	  }
412	}
