422	/** Выполняет операцию движка синхронно. `exec` выполняет операцию кошелька или бросает ошибку. */
423	export function runSync<T>(gen: EngineGen<T>, exec: (op: WalletOp) => number): T {
424	  let r = gen.next();
425	  while (!r.done) {
426	    let balance: number;
427	    try {
428	      balance = exec(r.value);
429	    } catch (e) {
430	      r = gen.throw(e);
431	      continue;
432	    }
433	    r = gen.next(balance);
434	  }
435	  return r.value;
436	}
