441	  while (!r.done) {
442	    let balance: number;
443	    try {
444	      balance = await exec(r.value);
445	    } catch (e) {
446	      r = gen.throw(e);
447	      continue;
448	    }
449	    r = gen.next(balance);
450	  }
451	  return r.value;
452	}
