533	/** Читает JSON-тело запроса. Пустое тело — `undefined`, битый JSON — `PlatformError('INVALID_REQUEST')`. */
534	export async function readJson(req: http.IncomingMessage): Promise<unknown> {
535	  const chunks: Buffer[] = [];
536	  let size = 0;
537	  for await (const chunk of req) {
