560	  const names = ['localhost', '127.0.0.1', '[::1]'];
561	  if (!WILDCARD_HOSTS.has(bindHost)) names.push((bindHost.includes(':') ? `[${bindHost}]` : bindHost).toLowerCase());
562	  const allowed = names.flatMap((n) => (port === 80 ? [`${n}:80`, n] : [`${n}:${port}`]));
