584	/** Отправляет ошибку в формате `{ error: { code, message } }`; неизвестная ошибка — 500 `INTERNAL_ERROR`. */
585	export function sendError(res: http.ServerResponse, e: unknown, extra: Record<string, unknown> = {}): void {
586	  const err = e instanceof PlatformError ? e : new PlatformError('INTERNAL_ERROR');
587	  if (!(e instanceof PlatformError)) console.error(e);
588	  else if (err.detail !== undefined) console.error(`${err.code}: ${err.detail}`);
