141	/**
142	 * Защита API от запросов со сторонних сайтов (CSRF): заголовок `Origin`, если он есть, должен совпадать с `Host`
143	 * (сам `Host` уже проверен по белому списку в `checkLocalHost`), а непустое тело — иметь тип `application/json`.
144	 */
145	function checkSameOrigin(req: http.IncomingMessage): void {
146	  const origin = req.headers.origin;
147	  if (origin !== undefined) {
148	    let host: string | undefined;
149	    try {
150	      host = new URL(origin).host;
151	    } catch {
152	      host = undefined;
153	    }
154	    if (!host || host !== req.headers.host) throw new PlatformError('FORBIDDEN');
155	  }
156	  checkJsonBody(req);
157	}
158	
159	function sendFile(req: http.IncomingMessage, res: http.ServerResponse, file: string): void {
160	  let data: Buffer;
161	  try {
162	    if (!fs.statSync(file).isFile()) throw new Error('not a file');
163	    data = fs.readFileSync(file);
164	  } catch {
165	    throw new PlatformError('NOT_FOUND');
166	  }
167	  const type = CONTENT_TYPES[path.extname(file).toLowerCase()] ?? 'application/octet-stream';
168	  res.writeHead(200, { 'content-type': type, 'content-length': data.length, 'cache-control': 'no-cache' });
169	  res.end(req.method === 'HEAD' ? undefined : data);
170	}
  1	/** Клиент кошелька для ядра: выполняет операции движка (`WalletOp`) по HTTP через `node:http`. */
  2	import http from 'node:http';
  3	import { PlatformError, messageOf } from '../shared/errors.ts';
  4	import type { WalletOp } from './engine.ts';
  5	
  6	const TIMEOUT_MS = 5000;
  7	/** Заголовок с общим секретом кошелька (как `WALLET_TOKEN_HEADER` в `platform/wallet`). */
  8	const TOKEN_HEADER = 'x-wallet-token';
  9	
 10	/**
 11	 * Создаёт исполнитель операций кошелька по адресу `walletUrl`; `token`, если задан, уходит в заголовке `x-wallet-token`.
 12	 * `402` → `INSUFFICIENT_FUNDS`; сеть, таймаут, `5xx` → `WALLET_UNAVAILABLE`; прочие отказы → `INTERNAL_ERROR`.
 13	 */
 14	export function walletExecutor(walletUrl: string, token?: string): (op: WalletOp) => Promise<number> {
 15	  return async (op) => {
 16	    const res =
 17	      op.kind === 'balance'
 18	        ? await call(walletUrl, token, 'GET', '/balance')
 19	        : await call(walletUrl, token, 'POST', `/${op.kind}`, { txId: op.txId, roundId: op.roundId, amount: op.amount });
 20	    const body = res.body as { balance?: unknown; error?: { code?: unknown } } | undefined;
 21	    if (res.status === 200 && typeof body?.balance === 'number') return body.balance;
 22	    if (res.status === 402) throw new PlatformError('INSUFFICIENT_FUNDS');
 23	    if (res.status >= 500 || res.status === 200) throw new PlatformError('WALLET_UNAVAILABLE');
 24	    throw new PlatformError('INTERNAL_ERROR', `Кошелёк отклонил операцию: ${String(body?.error?.code ?? res.status)}`);
 25	  };
 26	}
 27	
 28	function call(base: string, token: string | undefined, method: string, urlPath: string, body?: unknown): Promise<{ status: number; body: unknown }> {
 29	  const payload = body === undefined ? undefined : JSON.stringify(body);
 30	  return new Promise((resolve, reject) => {
 31	    const fail = (e: unknown): void => reject(new PlatformError('WALLET_UNAVAILABLE', `Кошелёк недоступен: ${messageOf(e)}`));
 32	    const req = http.request(
 33	      new URL(urlPath, base),
 34	      {
 35	        method,
 36	        timeout: TIMEOUT_MS,
 37	        headers: {
 38	          ...(token === undefined ? {} : { [TOKEN_HEADER]: token }),
 39	          ...(payload === undefined ? {} : { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) }),
 40	        },
 41	      },
 42	      (res) => {
 43	        const chunks: Buffer[] = [];
 44	        res.on('data', (c: Buffer) => chunks.push(c));
 45	        res.on('error', fail);
 46	        res.on('end', () => {
 47	          let parsed: unknown;
 48	          try {
 49	            parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'));
 50	          } catch {
 51	            parsed = undefined;
 52	          }
 53	          resolve({ status: res.statusCode ?? 0, body: parsed });
 54	        });
 55	      },
 56	    );
 57	    req.on('timeout', () => req.destroy(new Error('timeout')));
 58	    req.on('error', fail);
 59	    if (payload !== undefined) req.write(payload);
 60	    req.end();
 61	  });
 62	}
  1	/** Хранилища раундов: в памяти (testkit) и на диске (`data/rounds.json`, ядро). */
  2	import fs from 'node:fs';
  3	import path from 'node:path';
  4	import type { RoundRecord, RoundStore } from './engine.ts';
  5	
  6	/** Раунды в памяти. Записи хранятся как JSON, поэтому чтение всегда даёт независимую копию. */
  7	export class MemoryRoundStore implements RoundStore {
  8	  /** Раунды по `roundId` в виде JSON-строк. */
  9	  protected readonly rounds = new Map<string, string>();
 10	  readonly #openByGame = new Map<string, string>();
 11	
 12	  /** Раунд по идентификатору. */
 13	  get(roundId: string): RoundRecord | undefined {
 14	    const s = this.rounds.get(roundId);
 15	    return s === undefined ? undefined : (JSON.parse(s) as RoundRecord);
 16	  }
 17	
 18	  /** Открытый раунд игры, если есть. */
 19	  findOpen(gameId: string): RoundRecord | undefined {
 20	    const id = this.#openByGame.get(gameId);
 21	    return id === undefined ? undefined : this.get(id);
 22	  }
 23	
 24	  /** Сохраняет раунд целиком. */
 25	  save(round: RoundRecord): void {
 26	    this.rounds.set(round.roundId, JSON.stringify(round));
 27	    if (round.status === 'open') this.#openByGame.set(round.gameId, round.roundId);
 28	    else if (this.#openByGame.get(round.gameId) === round.roundId) this.#openByGame.delete(round.gameId);
 29	  }
 30	
 31	  /** Удаляет раунд (ставку которого кошелёк точно не списал). */
 32	  delete(roundId: string): void {
 33	    const round = this.get(roundId);
 34	    if (!round) return;
 35	    this.rounds.delete(roundId);
 36	    if (this.#openByGame.get(round.gameId) === roundId) this.#openByGame.delete(round.gameId);
 37	  }
 38	}
 39	
 40	/** Раунды на диске: файл перечитывается при создании и перезаписывается после каждого изменения. */
 41	export class FileRoundStore extends MemoryRoundStore {
 42	  readonly #file: string;
 43	
 44	  /** @param file путь к `rounds.json`; каталог создаётся при необходимости */
 45	  constructor(file: string) {
 46	    super();
 47	    this.#file = file;
 48	    if (fs.existsSync(file)) {
 49	      const data = JSON.parse(fs.readFileSync(file, 'utf8')) as { rounds?: Record<string, RoundRecord> };
 50	      for (const r of Object.values(data.rounds ?? {})) super.save(r);
 51	    }
 52	  }
 53	
 54	  /** Сохраняет раунд и записывает файл (через временный файл и rename). */
 55	  override save(round: RoundRecord): void {
 56	    super.save(round);
 57	    this.#write();
 58	  }
 59	
 60	  /** Удаляет раунд и записывает файл. */
 61	  override delete(roundId: string): void {
 62	    super.delete(roundId);
 63	    this.#write();
 64	  }
 65	
 66	  #write(): void {
 67	    const body = [...this.rounds].map(([id, json]) => `${JSON.stringify(id)}:${json}`).join(',\n');
 68	    fs.mkdirSync(path.dirname(this.#file), { recursive: true });
 69	    const tmp = `${this.#file}.tmp`;
 70	    fs.writeFileSync(tmp, `{"rounds":{\n${body}\n}}\n`);
 71	    fs.renameSync(tmp, this.#file);
 72	  }
 73	}
  1	/** Автоподключение игр: находит `<gamesDir>/*\/manifest.json` и загружает серверные модули. */
  2	import fs from 'node:fs';
  3	import path from 'node:path';
  4	import { pathToFileURL } from 'node:url';
  5	import type { GameModule } from '../sdk/types.ts';
  6	import { messageOf } from '../shared/errors.ts';
  7	
  8	/** Манифест игры `{ id, title, server, ui }`. */
  9	export interface GameManifest {
 10	  id: string;
 11	  title: string;
 12	  server: string;
 13	  ui: string;
 14	}
 15	
 16	/** Подключённая игра: манифест, серверный модуль и абсолютный путь к интерфейсу. */
 17	export interface LoadedGame {
 18	  manifest: GameManifest;
 19	  module: GameModule;
 20	  /** Каталог игры. */
 21	  dir: string;
 22	  /** Абсолютный путь к файлу интерфейса (`ui` из манифеста). */
 23	  uiFile: string;
 24	}
 25	
 26	const ID_RE = /^[a-z0-9][a-z0-9_-]*$/;
 27	
 28	/**
 29	 * Загружает игры из каталога, отсортированные по `id`. Некорректный манифест или модуль
 30	 * не роняет загрузку: игра пропускается с предупреждением в лог.
 31	 */
 32	export async function loadGames(gamesDir: string, log: (msg: string) => void = console.warn): Promise<LoadedGame[]> {
 33	  if (!fs.existsSync(gamesDir)) return [];
 34	  const loaded = new Map<string, LoadedGame>();
 35	  const dirs = fs
 36	    .readdirSync(gamesDir, { withFileTypes: true })
 37	    .filter((d) => d.isDirectory())
 38	    .map((d) => d.name)
 39	    .sort();
 40	  for (const name of dirs) {
 41	    const dir = path.join(gamesDir, name);
 42	    const manifestFile = path.join(dir, 'manifest.json');
 43	    if (!fs.existsSync(manifestFile)) continue;
 44	    try {
 45	      const manifest = parseManifest(fs.readFileSync(manifestFile, 'utf8'));
 46	      if (loaded.has(manifest.id)) throw new Error(`игра с id "${manifest.id}" уже подключена`);
 47	      const serverFile = inside(dir, manifest.server);
 48	      const uiFile = inside(dir, manifest.ui);
 49	      const mod = (await import(pathToFileURL(serverFile).href)) as { default?: unknown };
 50	      const game = checkModule(mod.default, manifest.id);
 51	      loaded.set(manifest.id, { manifest, module: game, dir, uiFile });
 52	    } catch (e) {
 53	      log(`[core] игра в ${dir} пропущена: ${messageOf(e)}`);
 54	    }
 55	  }
 56	  return [...loaded.values()].sort((a, b) => (a.manifest.id < b.manifest.id ? -1 : a.manifest.id > b.manifest.id ? 1 : 0));
 57	}
 58	
 59	function parseManifest(text: string): GameManifest {
 60	  const m = JSON.parse(text) as Partial<Record<keyof GameManifest, unknown>> | null;
 61	  if (!m || typeof m !== 'object') throw new Error('манифест не объект');
 62	  for (const key of ['id', 'title', 'server', 'ui'] as const) {
 63	    if (typeof m[key] !== 'string' || !m[key]) throw new Error(`в манифесте нет строки "${key}"`);
 64	  }
 65	  if (!ID_RE.test(m.id as string)) throw new Error(`недопустимый id "${String(m.id)}"`);
 66	  return { id: m.id as string, title: m.title as string, server: m.server as string, ui: m.ui as string };
 67	}
 68	
 69	function inside(dir: string, rel: string): string {
 70	  const full = path.resolve(dir, rel);
 71	  if (!full.startsWith(dir + path.sep)) throw new Error(`путь "${rel}" выходит за каталог игры`);
 72	  if (!fs.existsSync(full)) throw new Error(`файл "${rel}" не найден`);
 73	  return full;
 74	}
 75	
 76	function checkModule(mod: unknown, id: string): GameModule {
 77	  const g = mod as Partial<GameModule> | undefined;
 78	  if (!g || typeof g !== 'object') throw new Error('серверный модуль не экспортирует default');
 79	  for (const fn of ['validateParams', 'start', 'action', 'publicView'] as const) {
 80	    if (typeof g[fn] !== 'function') throw new Error(`в модуле нет функции ${fn}`);
 81	  }
 82	  if (g.id !== id) throw new Error(`id модуля "${String(g.id)}" не совпадает с манифестом "${id}"`);
 83	  return g as GameModule;
 84	}

