 82	    checkLocalHost(req, bindHost);
 83	    // GET /api/games
 84	    if (parts.length === 1 && parts[0] === 'games' && method === 'GET') {
 85	      return sendJson(res, 200, games.map((g) => ({ id: g.manifest.id, title: g.manifest.title })));
 86	    }
 87	    // GET /api/balance — для оболочки
 88	    if (parts.length === 1 && parts[0] === 'balance' && method === 'GET') {
 89	      return sendJson(res, 200, { balance: await exec({ kind: 'balance' }) });
 90	    }
 91	    if (method === 'POST' && parts.length === 3) {
 92	      checkSameOrigin(req);
 93	      const [kind, id, verb] = parts as [string, string, string];
 94	      if (kind === 'games' && verb === 'open') {
 95	        await readJson(req);
 96	        return sendJson(res, 200, await run(() => engine.open(id)));
 97	      }
 98	      if (kind === 'games' && verb === 'rounds') {
 99	        const body = ((await readJson(req)) ?? {}) as { bet?: unknown; params?: unknown };
100	        return sendJson(res, 200, await run(() => engine.startRound(id, body.bet, body.params)));
101	      }
102	      if (kind === 'rounds' && verb === 'actions') {
103	        const body = ((await readJson(req)) ?? {}) as { action?: unknown };
104	        return sendJson(res, 200, await run(() => engine.action(id, body.action)));
105	      }
106	    }
107	    throw new PlatformError('NOT_FOUND');
108	  };
109	
110	  const server = http.createServer(async (req, res) => {
111	    try {
112	      const url = new URL(req.url ?? '/', 'http://core');
113	      const parts = url.pathname.split('/').filter(Boolean).map((p) => decodeURIComponent(p));
114	      if (parts[0] === 'api') return await handleApi(req, res, parts.slice(1));
115	      if (req.method !== 'GET' && req.method !== 'HEAD') throw new PlatformError('NOT_FOUND');
116	      if (url.pathname === '/' || url.pathname === '/index.html') return sendFile(req, res, SHELL_FILE);
117	      if (url.pathname === '/sdk.js') return sendFile(req, res, SDK_FILE);
118	      if (parts[0] === 'games' && parts[1]) {
119	        const game = byId.get(parts[1]);
120	        if (!game) throw new PlatformError('GAME_NOT_FOUND');
121	        if (parts.length === 2 && !url.pathname.endsWith('/')) {
122	          res.writeHead(301, { location: `/games/${encodeURIComponent(parts[1])}/` });
123	          return void res.end();
124	        }
125	        const uiDir = path.dirname(game.uiFile);
126	        const rest = parts.slice(2);
127	        const file = rest.length === 0 ? game.uiFile : path.resolve(uiDir, ...rest);
128	        if (file !== game.uiFile && !file.startsWith(uiDir + path.sep)) throw new PlatformError('NOT_FOUND');
129	        return sendFile(req, res, file);
130	      }
131	      throw new PlatformError('NOT_FOUND');
132	    } catch (e) {
133	      if (e instanceof URIError) return sendError(res, new PlatformError('INVALID_REQUEST'));
134	      sendError(res, e);
135	    }
136	  });
137	
138	  return listen(server, opts.port, bindHost);
139	}
