    83	    if (typeof v !== 'number' || !Number.isFinite(v) || v < 0 || v >= 1) {
    84	      throw new RangeError(`fixedRng: значение ${v} вне [0, 1)`);
    85	    }
    86	  }
    87	  const queue = [...values];
    88	  let i = 0;
    89	  return {
    90	    next(): number {
    91	      if (i >= queue.length) throw new Error('fixedRng exhausted');
    92	      return queue[i++] as number;
    93	    },
    94	  };
    95	}
