    11	  'use strict';
    12	
    13	  var match = /^\/games\/([^/]+)/.exec(window.location.pathname);
    14	  var gameId = match ? decodeURIComponent(match[1]) : null;
    15	  var roundId = null;
    16	
    17	  function fail(code, message) {
    18	    return Promise.reject({ code: code, message: message || code });
    19	  }
    20	
    21	  function post(path, body) {
    22	    return fetch(path, {
    23	      method: 'POST',
