    22	export type { RunningServer };
    23	
    24	/** Начальный баланс игрока. */
    25	export const START_BALANCE = 100;
    26	/** Единственный игрок. */
    27	export const PLAYER_ID = 'player-1';
    28	
    29	/** Запись журнала транзакций кошелька. */
